factories["p53"]=function(){return [{"id": "KBZ6-DAILY", "frequency": "Each operating day / shift route", "tasks": ["Record RPM and suction, interstage, and discharge pressures and temperatures at a repeatable load point.", "Record bearing temperatures where instrumented.", "Record frame oil pressure downstream of the filter and frame inlet oil temperature.", "Record cylinder valve-cap temperatures and oil-filter differential pressure.", "Verify frame oil level near mid-sight-glass while running and check for foam.", "Verify force-feed lubricator reservoir level at overflow line.", "Record packing vent/drain temperature and inspect distance-piece and VVCP vents for leakage.", "Verify force-feed divider-block cycle time against the unit-specific lube plate or lube sheet.", "Inspect ARV indicator, leaks, unusual noise, and vibration.", "Review scrubber levels, dumps, cooler operation, and package-specific checks."], "references": [36, 37, 74, 77]}, {"id": "KBZ6-MONTHLY", "frequency": "Monthly", "tasks": ["Complete daily tasks.", "Function-test required safety shutdowns per approved site procedure.", "Collect a hot, running frame-oil sample and submit for viscosity, particle count, spectroscopy, and FTIR.", "Review oil-analysis trend for lead, tin, copper, water/coolant, oxidation, viscosity, and contamination.", "Record all active cylinder clearance-device settings."], "references": [37, 53]}, {"id": "KBZ6-4000H", "frequency": "4000 operating hours or six months", "tasks": ["Complete daily and monthly tasks.", "Inspect and clean crankcase breather filter.", "Drain and replace force-feed lubricator box oil.", "Clean or replace the applicable force-feed inlet/sintered filter.", "Replace frame oil filter and inspect removed element and vessel for debris.", "Change frame oil unless approved condition-based strategy and analysis justify another interval.", "Clean oil strainer and inspect crankcase/guide compartments for debris.", "Lubricate and stroke VVCP stems, returning each to documented setting.", "Perform cylinder lubrication paper test.", "Re-torque hold-down fasteners and inspect soft foot/top-plane condition.", "Check coupling alignment.", "Inspect and clean inlet screens."], "references": [38, 52, 80, 81]}, {"id": "KBZ6-8000H", "frequency": "8000 operating hours or one year", "tasks": ["Complete lower-interval tasks.", "Inspect force-feed lubricator cams, gears, and followers.", "Pressure-test distribution blocks.", "Measure and trend main-bearing, connecting-rod-bearing, crankshaft-thrust, crosshead, and piston-rod runout clearances.", "Remove and inspect/refurbish compressor valves unless an approved valve-specific interval applies.", "Inspect cylinder bores, piston rings, wear bands, piston rods, VVCPs, and unloaders as equipped.", "Rebuild piston-rod pressure packing cases.", "Calibrate required instrumentation.", "Inspect and adjust chains.", "Check gas-containment fastener torque."], "references": [38, 39, 40, 72, 98, 104, 147]}, {"id": "KBZ6-16000H", "frequency": "16000 operating hours or two years", "tasks": ["Complete lower-interval tasks.", "Perform deferred valve inspection where approved for applicable valve types.", "Rebuild oil-wiper cases.", "Rebuild suction-unloader and pneumatic-pocket actuators as equipped.", "Inspect chain and sprockets for stretch, undercut, and damage."], "references": [40, 142]}, {"id": "KBZ6-32000H", "frequency": "32000 operating hours or four years", "tasks": ["Complete lower-interval tasks.", "Remove crosshead pins and measure pin/bushing clearances.", "Inspect crosshead pin end caps and thru-bolts.", "Inspect piston ring grooves for wear."], "references": [40, 117, 118]}, {"id": "KBZ6-48000H", "frequency": "48000 operating hours or six years", "tasks": ["Complete lower-interval tasks.", "Replace lubricator distribution blocks.", "Replace crosshead and connecting-rod bushings.", "Replace connecting-rod bearings and main bearings.", "Replace auxiliary-end torsional damper if applicable.", "Replace auxiliary-end chain idler sprocket assemblies."], "references": [40, 127, 131, 142]}, {"id": "KBZ6-POST-MAJOR-MAINT", "frequency": "After major driveline, bearing, piston/rod, packing, or oil-system maintenance", "tasks": ["Verify isolation removal and approved return-to-service checklist.", "Pre-lube for 10-15 minutes at required pressure before turning or starting.", "Verify free rotation where required and account for all tools/materials.", "Verify force-feed system is fully purged with correct lubricant.", "Use break-in lubrication rate where required and return to normal rate after approved duration.", "Monitor oil pressure, temperature, filter differential, bearing temperatures, vibration, leakage, and abnormal noise.", "Perform staged run and post-run internal inspection when bearings were replaced.", "Document all measurements, parts, clearances, and findings."], "references": [59, 77, 98, 109, 127, 133]}];};
