  out.labels=[{text:'P-1620 / one-stage liquid pump',p:[0,13,8],throwIndex:0},{text:'SUCTION / liquid NGL /521',p:[0,8,30],throwIndex:0},{text:'DISCHARGE / liquid /shared532',p:[21,18,7],throwIndex:0},{text:'Plan52 BUFFER - not product',p:[-13,22,-1],throwIndex:2},{text:'Bearing oil - separate',p:[6,7,-9],throwIndex:1,circuit:'frame'}];
  out.coverage12MP=[['Source and owner','One existing P-1620 booster. PWH family manual reused, M2160 roles retained with current532 correction. No new installed component records.'],['Moving internals','Single impeller, shaft/key/locknut, driver/fan/coupling, bearing elements, seal-face and oil-ring teaching motion. Fitted dimensions/parts remain unassigned.'],['Liquid and phase','Normal liquid through eye/impeller/volute. Cavitation bubbles and low-flow heating are optional abnormal lessons, not plant-phase predictions.'],['Separate fluids','NGL product, bearing oil and Plan52 buffer liquid do not share a simulated pipe. RO-1620 remains a support vent restriction.'],['Not established','Selected curve/NPSHR, impeller trim/vane count, cartridge BOM, field tubing and exact thermodynamics remain unresolved, not invented.']];
