 function icon(n){var shapes='<rect x="105" y="15" width="100" height="58" rx="9" fill="none" stroke="currentColor" stroke-width="2"/><path d="M155 8v72" stroke="currentColor" stroke-width="3"/>';for(var i=0;i<n/2;i++){var y=23+i*(n===2?0:18);shapes+='<path d="M40 '+y+'h230" stroke="currentColor" stroke-width="2"/><rect x="23" y="'+(y-6)+'" width="48" height="13" rx="4" fill="#22546e" stroke="currentColor"/><rect x="240" y="'+(y-6)+'" width="48" height="13" rx="4" fill="#22546e" stroke="currentColor"/>';}return '<svg viewBox="0 0 310 90" aria-hidden="true">'+shapes+'</svg>';}
 /*12NL: project the CURRENT catalog once per ID; never append an independent
    hard-coded future list. Keep the actual model objects, owners and lessons intact.
    This helper lives inside the runtime because it is serialized into the iframe.*/
 function trainingMenuCards12NL(){
  var cards=[],seen=Object.create(null),titles={demeth:'Demethanizer tower',stabilizer:'Stabilizer tower',exchangers:'Heat exchangers',reboilers:'Reboilers'};
  data.models.forEach(function(m){
   if(!m||!m.id||seen[m.id])return;
   seen[m.id]=true;cards.push(m);
  });
  //12OL: only existing active model entries are launch cards; future scope stays in source history.
  return cards;
 }
