 /* 12MV: source-preserving study tools. No plant state, storage or process writes. */
 var studio12MV={system:'all',allAssemblies:true,only:null,wide:false,review:null,lastPick:null};
 var systemNames12MV={all:'All systems',process:'Product flow and gas ends',motion:'Drive and moving mechanism',bearings:'Bearings and lubrication interfaces',seals:'Seals, packing and barriers',oil:'Circulating oil and cooling',forcefeed:'Cylinder / packing force-feed',hydraulic:'Actuation and capacity control',instruments:'Instruments and protection',structure:'Casings, supports and guards'};
 function systemFor12MV(p){var text=(p.name+' '+p.type+' '+p.id).toLowerCase(),c=p.circuit||'';
  if(/sensor|transducer|transmitter|tachometer|pickup|vibration|pressure.tap|temperature.tap|gauge|monitor|instrument|thermowell|feedback|relief|protection|equalizer|ate-spool/.test(text)||c==='signal')return 'instruments';
  if(c==='hydraulic'||/slide|actuator|solenoid|igv|guide.vane|unloader/.test(text))return 'hydraulic';
  if(/packing|labyrinth|shaft.seal|wheel.seal|seal.gas|seal.weep|buffer|heat.barrier|oil.wiper|distance.piece/.test(text)||c==='seal'||c==='buffer'||c==='drain')return 'seals';
  if(c==='forcefeed'||/divider|force.feed|lubricator|injection.check|metering.tube/.test(text))return 'forcefeed';
  if(/bearing|crosspin|pin.bushing|oil.film|guiding.surface|thrust.*bearing/.test(text))return 'bearings';
  if(c==='frame'||c==='return'||c==='gearbox'||/oil.sump|oil.filter|oil.cooler|oil.pump|oil.strainer|pre.lube|breather|sightglass|oiler|oil.ring/.test(text))return 'oil';
  if(/coupling|motor|shaft|crank|connecting.rod|conrod|crosshead|piston|impeller|rotor|bull.gear|pinion|expander.wheel|stretch.rod|chain/.test(text)&&!/housing|casing|guard|guide/.test(text))return 'motion';
  if(/suction|discharge|gas|propane|product|liquid|gallery|manifold|diffuser|volute|clearance|head.end|valve|cylinder|barrel|coalescer|separator|flow|screen|inlet|outlet|nozzle|pocket|check|throat|wear.ring|bottle|scrubber/.test(text)||c==='process'||c==='product'||c==='propane')return 'process';
  return 'structure';
 }
